style.css:
@-moz-document domain("discord.com") {
/* 1. Variables globales */
    .theme-light, .theme-dark, :root {
        --background-primary: transparent !important;
        --background-secondary: transparent !important;
        --background-secondary-alt: transparent !important;
        --background-tertiary: transparent !important;
        --background-mobile-primary: transparent !important;
        --background-mobile-secondary: transparent !important;
        --background-floating: rgba(255, 237, 241, 0.87) !important;
        
        --background-modifier-hover: rgba(0, 0, 0, 0.05) !important;
        --background-modifier-active: rgba(0, 0, 0, 0.1) !important;
        --background-modifier-selected: rgba(0, 0, 0, 0.1) !important;
    }

    body, 
    [class*="appMount_"], 
    [class*="bg_"], 
    [class*="chat_"], 
    [class*="chatContent_"] {
        color: rgb(94, 87, 78) !important;
        font-family: "Times New Roman", serif !important;
        background-image: url("https://i.imgur.com/XUJ7F5o.jpeg") !important;
        background-repeat: no-repeat !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
    }

    [class*="mainContent_"],
    [class*="pageWrapper_"],
    [class*="sidebar_"] > *,
    [class*="sidebar_"] [class*="container_"],
    [class*="sidebar_"] [class*="scroller_"],
    [class*="sidebar_"] [class*="privateChannels_"],
    [class*="sidebar_"] nav {
        background: transparent !important;
        background-color: transparent !important;
    }

    [class*="panels_"] > [class*="container_"] {
        background-color: #FFEDF1 !important;
        box-shadow: 0px 4px 12px rgba(109, 79, 79, 0.3) !important;
    }

   
    [class*="sidebar_"] {
        width: 375px !important;
        height: 100vh !important;
        background-image: url("https://i.imgur.com/Cv4uRmT.jpeg") !important;
        background-repeat: no-repeat !important;
        background-size: cover !important;
        background-position: center !important;
    }
  
    [class*="sidebar_"] [class*="header_"],
    section[class*="title_"],
    [class*="container_"][class*="themed_"] {
      background-color: #FFEDF1 !important;
      box-shadow: 0px 4px 12px rgba(109, 79, 79, 0.3) !important;
      z-index: 10 !important;
    }
    [class*="title_"] [class*="children_"],
    [class*="title_"] [class*="toolbar_"],
    [class*="header_"] [class*="headerContent_"] {
      background: transparent !important;
    }


    [class*="focusLock_"],
    [class*="quickswitcher_"] [class*="scroller_"] {
        background: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }
  
    [class*="backdrop_"] {
        background-color: rgba(0, 0, 0, 0.7) !important;
    }
    [class*="categoryText_"] {
        color: #c08296 !important;
    }
    [class*="markup_"] h1, 
    [class*="markup_"] h2 {
        color: #a36b7c !important;
    }
    [class*="title_"] [class*="heading_"],
    [class*="titleWrapper_"] {
      color: #a36b7c !important;
      font-family: "Broadway" !important;
    }
}
